begin;
do $pricing$ declare x uuid:=public.cipmn_mock_seed_uuid('CIPMN-MOD-EL06:EXAM');begin insert into public.agilecert_exam_pricing_policies(id,examination_id,currency,standard_amount_minor,access_mode,attempts_included,bulk_cart_eligible,is_active)values(public.cipmn_mock_seed_uuid('CIPMN-MOD-EL06:PRICING-POLICY'),x,'NGN',2500000,'paid',1,true,true);end $pricing$;
do $verify$ declare x uuid:=public.cipmn_mock_seed_uuid('CIPMN-MOD-EL06:EXAM');a int;b int;c int;d int;e int;begin select count(*)into a from public.questions where examination_id=x and is_active and section='mcq';select count(*)into b from public.questions where examination_id=x and is_active and section='theory';select count(*)into c from public.question_answer_keys k join public.questions q on q.id=k.question_id where q.examination_id=x and q.section='mcq';select count(*)into d from public.question_options o join public.questions q on q.id=o.question_id where q.examination_id=x and q.section='mcq';select count(*)into e from public.theory_marking_rubrics r join public.questions q on q.id=r.question_id where q.examination_id=x and r.is_active and r.max_score=10 and jsonb_array_length(r.rubric->'criteria')=5;if a<>25 or b<>5 or c<>25 or d<>100 or e<>5 then raise exception 'EL06 verification failed';end if;end $verify$;
update public.examinations set exam_format='cipmn_mixed',status='published',updated_at=now()where id=public.cipmn_mock_seed_uuid('CIPMN-MOD-EL06:EXAM');
commit;
